INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (11, 37, 'theory', 'Quiz: the virtual DOM');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 37, 0, 'What does the function h(type, props, ...children) return?', '["A real DOM element", "A lightweight object describing a node (a vnode)", "An HTML string", "A promise"]', 1, 'h creates a plain object: the type, the props and the normalized children. The DOM is built later by the render function.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 37, 1, 'What does the diffing algorithm do when the node type has changed (div → span)?', '["Updates the props", "Replaces the whole node together with its subtree", "Ignores the change", "Compares the children by keys"]', 1, 'With different types, digging inside makes no sense, so the node is created anew.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 37, 2, 'Why does inserting at the start of a list without keys update every element?', '["That is how the browser works", "Diffing goes by index: each element is matched with its neighbor", "Because of CSS", "It is a bug in React"]', 1, 'By index, the first new item is compared with the old first one, and so on; with keys, items are matched by identity.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 37, 3, 'Why is the longest increasing subsequence (LIS) needed when diffing lists?', '["To sort the values", "To find the largest set of elements that stay in place, so the minimum of the others is moved", "To hash the keys", "To count the height of the list"]', 1, 'Elements from the LIS already stand in the correct relative order, so they are not moved.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (11, 37, 4, 'How does the Solid/Svelte approach differ from the virtual DOM?', '["They do not use JavaScript", "They update specific nodes directly (via a compiler or signals), without diffing trees", "They are always slower", "They do not support components"]', 1, 'Targeted updates instead of re-rendering and diffing a component: less work, but a different model and a more complex compiler.');
